 function monitoring(source){
  if(watch.paused||source.config?.enabled===false)return ['paused','Paused'];
  if(source.busy)return ['checking','Checking'];
  const state=source.monitoring_state||source.status;
  if(['paused','disabled','suspended'].includes(state))return ['paused','Paused'];
  if(state==='checking')return ['checking','Checking'];
  if(['access_required','authentication_required','authentication'].includes(state))return ['access_required','Authentication required'];
  if(['offline','unavailable'].includes(state))return ['offline','Offline'];
  if(state==='error'||source.error)return ['error','Error'];
  return ['monitoring','Monitoring'];
 }
 function metric(name,value,label){return `<div class="dl-metric ${value==='Unknown'?'is-unknown':''}">${icon(name)}<strong title="${escape(value)}">${escape(value)}</strong><span>${escape(label)}</span></div>`;}
 function filteredSources(){
  const needle=String(ui.watch_search||'').toLocaleLowerCase(),priority=ui.watch_priority;
  const rows=(watch?.sources||[]).filter(source=>{
   const config=source.config||{},counts=source.counts||{},status=monitoring(source)[0],search=[source.title,source.handle,source.platform,source.id].join(' ').toLocaleLowerCase();
   if(needle&&!search.includes(needle)||priority&&config.priority!==priority||ui.watch_platform&&source.platform!==ui.watch_platform)return false;
   return ({all:true,monitoring:status==='monitoring'||status==='checking',paused:status==='paused',instant:config.instant_download===true,review:Number(counts.review)>0,pending:Number(counts.pending??counts.ready??0)+Number(counts.active||0)>0,failed:Number(counts.failed)>0})[ui.watch_filter||'all']??true;
  });
  const rank={minimal:0,low:1,medium:2,normal:2,high:3,extra:4,critical:5,ultra:5},direction=ui.watch_sort==='name'?1:ui.watch_sort==='name_desc'?-1:ui.watch_direction==='asc'?1:-1;
  const value=source=>({priority:rank[source.config?.priority]??2,name:String(source.title||'').toLocaleLowerCase(),added:source.created,latest:dateNumber(source.latest?.published||source.latest?.upload_date),discovered:source.counts?.discovered,downloaded:source.counts?.downloaded,review:source.counts?.review,failed:source.counts?.failed,checked:source.last_success,status:monitoring(source)[1]})[ui.watch_sort==='name_desc'?'name':ui.watch_sort||'priority'];
  return rows.sort((left,right)=>{const a=value(left),b=value(right);if(a==null&&b!=null)return 1;if(b==null&&a!=null)return -1;const compare=typeof a==='string'?a.localeCompare(String(b)):Number(a||0)-Number(b||0);return compare*direction||String(left.id).localeCompare(String(right.id));});
 }
