   const nextOptions={...options,format:$('#watch-format').value,max_height:Number($('#watch-max-height').value),quality:$('#watch-quality').value,subtitle_languages:$('#watch-subtitle-languages').value,filename_template:$('#watch-template').value,subtitles:$('#watch-subtitles').checked,auto_subtitles:$('#watch-auto-subtitles').checked,embed_metadata:$('#watch-metadata').checked,thumbnail:false,playlist:false};delete nextOptions.cookies;
